<script setup lang="ts">
import { onLoad } from '@dcloudio/uni-app'
import { ref } from 'vue'
import ConsultantBottomNav from '../../components/ConsultantBottomNav.vue'
import AppCard from '../../components/AppCard.vue'
import { consultationRepository as api } from '../../services/api/consultation'
import type { AIHealthReport, HealthProfile, HealthReport, Observation } from '../../types/domain'
import type { DemoSession, HealthTimelineEvent } from '../../types/consultation'
import { uniApi as uni } from '../../services/platform/uni'
const session = ref<DemoSession>(); const userId = ref(''); const clientName = ref('客户'); const profile = ref<HealthProfile | null>(null); const reports = ref<HealthReport[]>([]); const observations = ref<Observation[]>([]); const timeline = ref<HealthTimelineEvent[]>([]); const aiReport = ref<AIHealthReport | null>(null); const loading = ref(true); const error = ref('')
onLoad(async (options) => { userId.value = options?.userId || ''; if (!userId.value) { loading.value = false; return } try { session.value = await api.login('consultant'); const result = await api.clientHealth(userId.value, session.value); profile.value = result.profile; reports.value = result.reports; observations.value = result.observations; timeline.value = result.timeline; aiReport.value = result.aiReport; clientName.value = result.profile?.userId || '客户' } catch (e) { error.value = (e as Error).message } finally { loading.value = false } })
</script>
<template><view class="page consultant-page"><view class="head"><view><text class="eyebrow">客户健康资料</text><text class="title">{{ clientName }}</text><text class="subtitle">完整专业洞察仅对健管师开放</text></view><text class="spark">✦</text></view><AppCard v-if="error" class="intro"><text class="intro-title">无法读取客户资料</text><text class="muted">{{ error }}</text></AppCard><text v-else-if="loading" class="muted loading">正在读取客户健康资料…</text><template v-else><AppCard class="profile-card"><text class="section-title">基础档案</text><text class="muted">{{ profile?.gender || '未填写' }} · {{ profile?.birthYear || '未填写出生年份' }} · {{ profile?.lifestyle || '未填写生活方式' }}</text><text class="muted">既往史：{{ profile?.medicalHistory || '暂无记录' }}</text><text class="muted">过敏史：{{ profile?.allergies || '暂无记录' }}</text></AppCard><view class="section-title">健康指标 · {{ observations.length }} 项</view><AppCard v-if="!observations.length" class="intro"><text class="intro-title">等待客户确认指标</text><text class="muted">客户确认报告解析结果后，指标会出现在这里。</text></AppCard><AppCard v-for="item in observations" :key="item.id" class="metric"><view class="metric-head"><text class="metric-name">{{ item.name }}</text><text :class="item.status === '正常' ? 'normal' : 'danger'">{{ item.status }}</text></view><text class="metric-value">{{ item.value }} {{ item.unit }}</text><text class="muted">参考：{{ item.reference }} · {{ item.measuredAt }}</text></AppCard><view class="section-title">资料时间线</view><AppCard v-for="item in timeline" :key="item.id" class="timeline"><text class="timeline-title">{{ item.title }}</text><text class="muted">{{ item.status }} · {{ item.occurredAt }}</text><text class="muted">{{ item.detail }}</text></AppCard><view class="section-title">报告与 AI 结果</view><AppCard class="report-card"><text class="report-title">已确认报告 {{ reports.filter(item => item.status === '解析成功').length }} 份</text><text class="muted">AI 结果：{{ aiReport?.summary || '暂未生成，等待分析任务' }}</text></AppCard></template><ConsultantBottomNav active="insights" /></view></template>
<style scoped>.consultant-page{padding-top:34rpx;padding-bottom:170rpx;background:#fffaf6}.head{display:flex;align-items:flex-end;justify-content:space-between;margin-bottom:30rpx}.eyebrow{display:block;color:#b37a57;font-size:22rpx}.title{display:block;margin-top:8rpx;color:#2a201c;font-size:42rpx;font-weight:800}.spark{width:74rpx;height:74rpx;border-radius:24rpx;color:#d96b2b;background:#fff0e5;font-size:40rpx;line-height:74rpx;text-align:center}.intro{padding:28rpx;background:#fff0e5}.intro-title{display:block;color:#9f5428;font-size:29rpx;font-weight:700}.intro .muted{margin-top:12rpx;color:#8a6857;line-height:1.65}.profile-card{padding:24rpx}.section-title{margin:34rpx 2rpx 16rpx;color:#2a201c;font-size:30rpx;font-weight:800}.profile-card .section-title{margin:0 0 12rpx}.muted{display:block;margin-top:9rpx;color:#8a7770;line-height:1.55}.metric{margin-top:14rpx;padding:22rpx}.metric-head{display:flex;justify-content:space-between}.metric-name{font-weight:700}.metric-value{display:block;margin-top:12rpx;font-size:34rpx;color:#c8652a}.timeline{margin-top:14rpx;padding:22rpx}.timeline-title{display:block;font-weight:700}.danger{color:#d85f42}.normal{color:#3d9b65}.report-card{padding:24rpx}.report-title{display:block;font-weight:700}.loading{margin-top:30rpx}.health-btn{width:100%;margin-top:18rpx;color:#c8652a;background:#fff0e5;border:0}</style>
